mapper.update:
UPDATE emp60_sign
   SET emp60_use_yn = #{r.useYn},
       emp60_note   = #{r.note}
 WHERE emp60_sign_id    = #{r.signId}
   AND emp60_person_id  = #{personId}
   AND emp60_company_id = #{companyId}

mapper.delete:
DELETE FROM emp60_sign
 WHERE emp60_sign_id    = #{signId}
   AND emp60_person_id  = #{personId}
   AND emp60_company_id = #{companyId}

